INSERT INTO `api_inazuma_eleven___hoja_1` (`id`, `Apodo`, `Nombre_Real`, `Descripcion`, `Imagenes`, `Posicion`, `Elemento`, `Genero`, `Equipo`, `PE`, `PT`, `Tiro`, `Fisico`, `Control`, `Defensa`, `Rapidez`, `Aguante`, `Valor`, `Juego`) VALUES
(1, 'Mark', 'Mark Evans', 'Enérgico capitán del Raimon. Nadie vive el fútbol como él.', 'https://raw.githubusercontent.com/ggdsrll/API-Inazuma-Eleven/main/InazumaEleven1/Jugadores/Raimon/Mark.png', 'PR', 'Montaña', 'Masculino', 'Raimon', 191, 184, 72, 72, 70, 77, 68, 69, 79, 'Inazuma Eleven 1'),
(2, 'Jack', 'Jack Wallside', 'Su gran cuerpo es como una pared que utiliza para que nadie pase.', 'https://raw.githubusercontent.com/ggdsrll/API-Inazuma-Eleven/main/InazumaEleven1/Jugadores/Raimon/Jack.png', 'DF', 'Montaña', 'Masculino', 'Raimon', 206, 165, 62, 68, 62, 66, 49, 54, 54, 'Inazuma Eleven 1'),
(3, 'Jim', 'Jim Wraith', 'Nadie ha podido ver jamás la mirada que esconde detrás de su flequillo.', 'https://raw.githubusercontent.com/ggdsrll/API-Inazuma-Eleven/main/InazumaEleven1/Jugadores/Raimon/Jim.png', 'DF', 'Bosque', 'Masculino', 'Raimon', 195, 140, 58, 53, 75, 59, 53, 62, 60, 'Inazuma Eleven 1'),
(4, 'Bobby', 'Bobby Shearer', 'Es despreocupado, pero pasional. Vivió un tiempo en Estados Unidos.', 'https://raw.githubusercontent.com/ggdsrll/API-Inazuma-Eleven/main/InazumaEleven1/Jugadores/Raimon/Bobby.png', 'DF', 'Bosque', 'Masculino', 'Raimon', 202, 176, 76, 61, 72, 76, 60, 70, 70, 'Inazuma Eleven 1'),
(5, 'Tod', 'Tod Ironside', 'Su cuerpo es pequeño, pero su coraje enorme. Da vidilla al equipo.', 'https://raw.githubusercontent.com/ggdsrll/API-Inazuma-Eleven/main/InazumaEleven1/Jugadores/Raimon/Tod.png', 'DF', 'Fuego', 'Masculino', 'Raimon', 184, 161, 54, 55, 53, 56, 59, 56, 65, 'Inazuma Eleven 1'),
(6, 'Nathan', 'Nathan Swift', 'Defensa veloz como un torbellino. Conoce a Mark desde hace tiempo.', 'https://raw.githubusercontent.com/ggdsrll/API-Inazuma-Eleven/main/InazumaEleven1/Jugadores/Raimon/Nathan.png', 'DF', 'Aire', 'Masculino', 'Raimon', 169, 156, 64, 58, 68, 54, 76, 58, 56, 'Inazuma Eleven 1'),
(7, 'Steve', 'Steve Grim', 'No destaca en nada, pero sus habilidades están bien equilibradas.', 'https://raw.githubusercontent.com/ggdsrll/API-Inazuma-Eleven/main/InazumaEleven1/Jugadores/Raimon/Steve.png', 'MD', 'Aire', 'Masculino', 'Raimon', 154, 144, 62, 64, 71, 64, 71, 71, 71, 'Inazuma Eleven 1'),
(8, 'Timmy', 'Tim Saunders', 'Sus gráciles movimientos y dominio del balón son fruto del kung-fu.', 'https://raw.githubusercontent.com/ggdsrll/API-Inazuma-Eleven/main/InazumaEleven1/Jugadores/Raimon/Timmy.png', 'MD', 'Bosque', 'Masculino', 'Raimon', 156, 149, 63, 76, 61, 60, 55, 48, 58, 'Inazuma Eleven 1'),
(9, 'Sam', 'Sam Kincaid', 'Va siempre a su ritmo aunque los demás le chinchen por ello.', 'https://raw.githubusercontent.com/ggdsrll/API-Inazuma-Eleven/main/InazumaEleven1/Jugadores/Raimon/Sam.png', 'MD', 'Fuego', 'Masculino', 'Raimon', 167, 136, 71, 57, 56, 56, 52, 56, 76, 'Inazuma Eleven 1'),
(10, 'Erik', 'Erik Eagle', 'Centrocampista excepcional. Le llaman \"El mago del campo\".', 'https://raw.githubusercontent.com/ggdsrll/API-Inazuma-Eleven/main/InazumaEleven1/Jugadores/Raimon/Erik.png', 'MD', 'Bosque', 'Masculino', 'Raimon', 240, 240, 79, 89, 99, 96, 79, 79, 74, 'Inazuma Eleven 1'),
(11, 'Jude', 'Jude Sharp', 'De sus botas sale fútbol de muchos quilates. El mejor en su posición.', 'https://raw.githubusercontent.com/ggdsrll/API-Inazuma-Eleven/main/InazumaEleven1/Jugadores/Raimon/Jude.png', 'MD', 'Aire', 'Masculino', 'Raimon', 191, 180, 63, 79, 79, 79, 76, 76, 68, 'Inazuma Eleven 1'),
(12, 'Max', 'Maxwell Carson', 'Por su pinta, nunca dirías que es un as de los deportes.', 'https://raw.githubusercontent.com/ggdsrll/API-Inazuma-Eleven/main/InazumaEleven1/Jugadores/Raimon/Max.png', 'DL', 'Aire', 'Masculino', 'Raimon', 156, 160, 60, 56, 78, 64, 60, 56, 62, 'Inazuma Eleven 1'),
(13, 'Kevin', 'Kevin Dradonfly', 'Goleador del Raimon. Algo arisco, pero se deja la piel por el equipo.', 'https://raw.githubusercontent.com/ggdsrll/API-Inazuma-Eleven/main/InazumaEleven1/Jugadores/Raimon/Kevin.png', 'DL', 'Bosque', 'Masculino', 'Raimon', 195, 144, 71, 60, 59, 61, 60, 64, 70, 'Inazuma Eleven 1'),
(14, 'Axel', 'Axel Blaze', 'Nuevo y carismático estudiante. Le llaman \"el punta legendario\".', 'https://raw.githubusercontent.com/ggdsrll/API-Inazuma-Eleven/main/InazumaEleven1/Jugadores/Raimon/Axel.png', 'DL', 'Fuego', 'Masculino', 'Raimon', 200, 176, 79, 66, 76, 64, 72, 68, 60, 'Inazuma Eleven 1'),
(15, 'Willy', 'William Glass', 'Un triunfador al que le quedan bien las gafas. O eso dice él...', 'https://raw.githubusercontent.com/ggdsrll/API-Inazuma-Eleven/main/InazumaEleven1/Jugadores/Raimon/Willy.png', 'DL', 'Bosque', 'Masculino', 'Raimon', 147, 168, 56, 51, 68, 57, 56, 53, 60, 'Inazuma Eleven 1'),
(16, 'Mask', 'Nathan Jones', 'Peligroso personaje que corta el césped del campo con una guadaña.', 'https://raw.githubusercontent.com/ggdsrll/API-Inazuma-Eleven/main/InazumaEleven1/Jugadores/Occult/Mask.png', 'PR', 'Aire', 'Masculino', 'Occult', 165, 156, 58, 56, 70, 68, 56, 60, 68, 'Inazuma Eleven 1'),
(17, 'Zombie', 'Rob Crombie', 'Por muchas patadas que le den es incapaz de sentir dolor.', 'https://raw.githubusercontent.com/ggdsrll/API-Inazuma-Eleven/main/InazumaEleven1/Jugadores/Occult/Zombie.png', 'PR', 'Montaña', 'Masculino', 'Occult', 200, 156, 47, 46, 50, 40, 51, 74, 56, 'Inazuma Eleven 1'),
(18, 'Styx', 'Russell Walk', 'Desde que hizo espiritismo, no sabe si su cuerpo le pertenece.', 'https://raw.githubusercontent.com/ggdsrll/API-Inazuma-Eleven/main/InazumaEleven1/Jugadores/Occult/Styx.png', 'DF', 'Bosque', 'Masculino', 'Occult', 140, 137, 60, 53, 60, 52, 63, 65, 58, 'Inazuma Eleven 1'),
(19, 'Franky', 'Ken Furan', 'Hace experimentos para crear vida, pero no les encuentra el pulso.', 'https://raw.githubusercontent.com/ggdsrll/API-Inazuma-Eleven/main/InazumaEleven1/Jugadores/Occult/Franky.png', 'DF', 'Montaña', 'Masculino', 'Occult', 151, 156, 55, 59, 47, 70, 52, 61, 48, 'Inazuma Eleven 1'),
(20, 'Undead', 'Jerry Fulton', 'Como cree que es inmortal, se pone en peligro a propósito.', 'https://raw.githubusercontent.com/ggdsrll/API-Inazuma-Eleven/main/InazumaEleven1/Jugadores/Occult/Undead.png', 'DF', 'Fuego', 'Masculino', 'Occult', 187, 132, 52, 58, 56, 61, 56, 79, 53, 'Inazuma Eleven 1'),
(21, 'Creepy', 'Jason Jones', 'Estudioso de seres fantásticos a los que echa la culpa de todo.', 'https://raw.githubusercontent.com/ggdsrll/API-Inazuma-Eleven/main/InazumaEleven1/Jugadores/Occult/Creepy.png', 'DF', 'Aire', 'Masculino', 'Occult', 151, 152, 52, 54, 57, 57, 60, 54, 63, 'Inazuma Eleven 1'),
(22, 'Jiangshi', 'Ray Mannings', 'Su cuerpo es tan rígido que al correr parece que vaya rebotando.', 'https://raw.githubusercontent.com/ggdsrll/API-Inazuma-Eleven/main/InazumaEleven1/Jugadores/Occult/Jiangshi.png', 'MD', 'Aire', 'Masculino', 'Occult', 145, 136, 55, 62, 60, 52, 56, 61, 62, 'Inazuma Eleven 1'),
(23, 'Mummy', 'Robert Mayer', 'Su piel se seca con suma facilidad y por eso se la cubre de vendajes.', 'https://raw.githubusercontent.com/ggdsrll/API-Inazuma-Eleven/main/InazumaEleven1/Jugadores/Occult/Mummy.png', 'MD', 'Bosque', 'Masculino', 'Occult', 187, 137, 54, 52, 60, 52, 62, 75, 61, 'Inazuma Eleven 1'),
(24, 'Grave', 'Alexander Brave', 'Experto en maleficios y brujerías. Enojarle es buscarse la ruina.', 'https://raw.githubusercontent.com/ggdsrll/API-Inazuma-Eleven/main/InazumaEleven1/Jugadores/Occult/Grave.png', 'MD', 'Fuego', 'Masculino', 'Occult', 180, 144, 57, 65, 60, 52, 71, 56, 55, 'Inazuma Eleven 1'),
(25, 'Wolfy', 'Troy Moon', 'Le llaman \"el licántropo\" porque al mirar la luna pierde el juicio.', 'https://raw.githubusercontent.com/ggdsrll/API-Inazuma-Eleven/main/InazumaEleven1/Jugadores/Occult/Wolfy.png', 'MD', 'Fuego', 'Masculino', 'Occult', 211, 153, 61, 70, 77, 52, 79, 69, 67, 'Inazuma Eleven 1'),
(26, 'Ghost', 'Mick Askley', 'Cree que no es humano y por eso lleva siempre el rostro cubierto.', 'https://raw.githubusercontent.com/ggdsrll/API-Inazuma-Eleven/main/InazumaEleven1/Jugadores/Occult/Ghost.png', 'MD', 'Bosque', 'Masculino', 'Occult', 143, 100, 55, 50, 54, 44, 48, 56, 54, 'Inazuma Eleven 1'),
(27, 'Blood', 'Burt Wolf', 'Al caer la noche juega como nadie. Bebe mucho zumo de tomate.', 'https://raw.githubusercontent.com/ggdsrll/API-Inazuma-Eleven/main/InazumaEleven1/Jugadores/Occult/Blood.png', 'MF', 'Montaña', 'Masculino', 'Occult', 184, 152, 68, 52, 52, 51, 56, 62, 60, 'Inazuma Eleven 1'),
(28, 'Dollman', 'Chuck Dollman', 'No recuerda nada de su pasado, cree que es un androide.', 'https://raw.githubusercontent.com/ggdsrll/API-Inazuma-Eleven/main/InazumaEleven1/Jugadores/Occult/Dollman.png', 'DL', 'Bosque', 'Masculino', 'Occult', 129, 104, 52, 53, 45, 48, 49, 53, 55, 'Inazuma Eleven 1'),
(29, 'Noir', 'Phil Noir', 'Sabe lo suyo de magia negra, y la emplea para maldecir a los rivales.', 'https://raw.githubusercontent.com/ggdsrll/API-Inazuma-Eleven/main/InazumaEleven1/Jugadores/Occult/Noir.png', 'DL', 'Bosque', 'Masculino', 'Occult', 121, 120, 52, 45, 48, 52, 52, 58, 45, 'Inazuma Eleven 1'),
(30, 'Alien', 'Uxley Allen', 'Cree en los ovnis y por eso, cada noche, observa las estrellas.', 'https://raw.githubusercontent.com/ggdsrll/API-Inazuma-Eleven/main/InazumaEleven1/Jugadores/Occult/Alien.png', 'DL', 'Aire', 'Masculino', 'Occult', 149, 112, 48, 51, 51, 50, 48, 55, 44, 'Inazuma Eleven 1'),
(31, 'Talisman', 'Johan Tassman ', 'Su \"don\" le permite contactar con espíritus de futbolistas.', 'https://raw.githubusercontent.com/ggdsrll/API-Inazuma-Eleven/main/InazumaEleven1/Jugadores/Occult/Talisman.png', 'DL', 'Bosque', 'Masculino', 'Occult', 171, 165, 62, 64, 56, 48, 60, 62, 63, 'Inazuma Eleven 1'),
(32, 'Boar', 'Charlie Boardfield', 'Bajo palos, parece un jabalí que sale a lo bestia a por balones.', 'https://raw.githubusercontent.com/ggdsrll/API-Inazuma-Eleven/main/InazumaEleven1/Jugadores/Wild/Boar.png', 'PR', 'Fuego', 'Masculino', 'Wild', 217, 100, 68, 44, 44, 69, 60, 62, 69, 'Inazuma Eleven 1'),
(33, 'Bullford', 'Chad Bulllord', 'Es tan glotón que, si se le acaba la comida, se pone hecho una furia.', 'https://raw.githubusercontent.com/ggdsrll/API-Inazuma-Eleven/main/InazumaEleven1/Jugadores/Wild/Bullford.png', 'PR', 'Fuego', 'Masculino', 'Wild', 171, 174, 41, 68, 48, 77, 31, 51, 64, 'Inazuma Eleven 1'),
(34, 'Toad', 'Peter Johnson', 'Salta una barbaridad. Su cuarto está lleno de peluches de ranas.', 'https://raw.githubusercontent.com/ggdsrll/API-Inazuma-Eleven/main/InazumaEleven1/Jugadores/Wild/Toad.png', 'DF', 'Bosque', 'Masculino', 'Wild', 167, 109, 48, 52, 48, 48, 54, 57, 50, 'Inazuma Eleven 1'),
(35, 'Fishman', 'Wilson Fishman', 'Aunque sabe un montón de animales marinos, no pone un pie en el agua.', 'https://raw.githubusercontent.com/ggdsrll/API-Inazuma-Eleven/main/InazumaEleven1/Jugadores/Wild/Fishman.png', 'DF', 'Bosque', 'Masculino', 'Wild', 167, 113, 52, 64, 51, 51, 51, 62, 51, 'Inazuma Eleven 1'),
(36, 'Racoon', 'Rocky Rackham', 'Es muy estricto con la higiene. No se come nada que no haya lavado.', 'https://raw.githubusercontent.com/ggdsrll/API-Inazuma-Eleven/main/InazumaEleven1/Jugadores/Wild/Racoon.png', 'DF', 'Bosque', 'Masculino', 'Wild', 123, 121, 53, 53, 53, 44, 51, 44, 47, 'Inazuma Eleven 1'),
(37, 'Lion', 'Leonard O\'Shea', 'No hay quien le lleve la contraria. Defiende su zona con zarpa férrea.', 'https://raw.githubusercontent.com/ggdsrll/API-Inazuma-Eleven/main/InazumaEleven1/Jugadores/Wild/Lion.png', 'DF', 'Montaña', 'Masculino', 'Wild', 195, 113, 78, 52, 47, 64, 55, 69, 68, 'Inazuma Eleven 1'),
(38, 'Monkey', 'Bruce Monkey', 'Con su pequeño cuerpo y rapidez de acróbata, lleva de cabeza al rival.', 'https://raw.githubusercontent.com/ggdsrll/API-Inazuma-Eleven/main/InazumaEleven1/Jugadores/Wild/Monkey.png', 'MD', 'Bosque', 'Masculino', 'Wild', 184, 100, 54, 64, 51, 48, 53, 52, 54, 'Inazuma Eleven 1'),
(39, 'Chameleon', 'Cham Lion', 'Disimula totalmente su presencia para robar balones de extranjis.', 'https://raw.githubusercontent.com/ggdsrll/API-Inazuma-Eleven/main/InazumaEleven1/Jugadores/Wild/Chameleon.png', 'MD', 'Aire', 'Masculino', 'Wild', 176, 101, 44, 45, 45, 55, 53, 60, 48, 'Inazuma Eleven 1'),
(40, 'Mouseman', 'Matt Mouseman', 'Es muy quesero, tanto que incluso zampa queso azul con mucho gusto.', 'https://raw.githubusercontent.com/ggdsrll/API-Inazuma-Eleven/main/InazumaEleven1/Jugadores/Wild/Mouseman.png', 'MD', 'Montaña', 'Masculino', 'Wild', 158, 112, 42, 50, 52, 44, 79, 54, 45, 'Inazuma Eleven 1'),
(41, 'Koala', 'Alan Coe', 'Un chavalín raro que dice estar más a gusto en un árbol que en el suelo.', 'https://raw.githubusercontent.com/ggdsrll/API-Inazuma-Eleven/main/InazumaEleven1/Jugadores/Wild/Koala.png', 'MD', 'Bosque', 'Masculino', 'Wild', 132, 112, 52, 45, 53, 51, 48, 46, 49, 'Inazuma Eleven 1'),
(42, 'Chicken', 'Hugo talgeese', 'Agobia a los rivales como un gallo cuando picotea el piso.', 'https://raw.githubusercontent.com/ggdsrll/API-Inazuma-Eleven/main/InazumaEleven1/Jugadores/Wild/Chicken.png', 'MD', 'Fuego', 'Masculino', 'Wild', 189, 101, 44, 52, 56, 46, 64, 67, 54, 'Inazuma Eleven 1'),
(43, 'Eagle', 'Steve Eagle', 'Detecta y se lanza sobre el rival con la agudeza visual de un águila.', 'https://raw.githubusercontent.com/ggdsrll/API-Inazuma-Eleven/main/InazumaEleven1/Jugadores/Wild/Eagle.png', 'MD', 'Aire', 'Masculino', 'Wild', 193, 148, 61, 68, 62, 52, 68, 71, 68, 'Inazuma Eleven 1'),
(44, 'Panda', 'Philip Anders', 'A primera vista parece bonachón y adorable, pero tiene muy mala uva.', 'https://raw.githubusercontent.com/ggdsrll/API-Inazuma-Eleven/main/InazumaEleven1/Jugadores/Wild/Panda.png', 'DL', 'Fuego', 'Masculino', 'Wild', 123, 132, 52, 51, 48, 52, 52, 51, 46, 'Inazuma Eleven 1'),
(45, 'Cheetah', 'Adrian Speed', 'Deja a todos sentados con su increíble marca de cien metros en diez segundos.', 'https://raw.githubusercontent.com/ggdsrll/API-Inazuma-Eleven/main/InazumaEleven1/Jugadores/Wild/Cheetah.png', 'DL', 'Aire', 'Masculino', 'Wild', 195, 133, 63, 47, 69, 55, 79, 42, 47, 'Inazuma Eleven 1'),
(46, 'Gorila', 'Gary Lancarster', 'Emplea su severo semblante y sólido cuerpo para invadir el área rival.', 'https://raw.githubusercontent.com/ggdsrll/API-Inazuma-Eleven/main/InazumaEleven1/Jugadores/Wild/Gorila.png', 'DL', 'Montaña', 'Masculino', 'Wild', 191, 108, 78, 66, 49, 64, 54, 52, 67, 'Inazuma Eleven 1'),
(47, 'Snake', 'Harry Snake', 'Al apoderarse del balón, parece que lo envuelve y ya no lo suelta.', 'https://raw.githubusercontent.com/ggdsrll/API-Inazuma-Eleven/main/InazumaEleven1/Jugadores/Wild/Snake.png', 'DL', 'Bosque', 'Masculino', 'Wild', 184, 112, 55, 63, 62, 49, 55, 65, 45, 'Inazuma Eleven 1'),
(48, 'Feldt', 'Thomas Feldt', 'Líder del Brain que se deshizo de sus dudas con un lavado de cerebro', 'https://raw.githubusercontent.com/ggdsrll/API-Inazuma-Eleven/main/InazumaEleven1/Jugadores/Brain/Feldt.png', 'PR', 'Bosque', 'Masculino', 'Brain', 206, 177, 75, 69, 68, 76, 75, 78, 76, 'Inazuma Eleven 1'),
(49, 'Under', 'Reg Underwood', 'Se sometió al experimento para sacar a su familia de la miseria.', 'https://raw.githubusercontent.com/ggdsrll/API-Inazuma-Eleven/main/InazumaEleven1/Jugadores/Brain/Under.png', 'PR', 'Bosque', 'Masculino', 'Brain', 121, 115, 44, 40, 40, 69, 48, 42, 70, 'Inazuma Eleven 1'),
(50, 'Waters', 'Neil Waters', 'Era tranquilo hasta que le lavaron el cerebro. Se ha vuelto agresivo.', 'https://raw.githubusercontent.com/ggdsrll/API-Inazuma-Eleven/main/InazumaEleven1/Jugadores/Brain/Waters.png', 'DF', 'Bosque', 'Masculino', 'Brain', 151, 101, 52, 48, 51, 52, 45, 54, 45, 'Inazuma Eleven 1'),
(51, 'Good', 'Noel Good', 'El lavado de cerebro consiguió que hiciera tareas de manera ordenada.', 'https://raw.githubusercontent.com/ggdsrll/API-Inazuma-Eleven/main/InazumaEleven1/Jugadores/Brain/Good.png', 'DF', 'Bosque', 'Masculino', 'Brain', 134, 117, 44, 44, 48, 55, 44, 48, 45, 'Inazuma Eleven 1'),
(52, 'Stronger', 'Terry Stronger', 'Ha sacrificado hasta su propia consciencia para tener más fuerza.', 'https://raw.githubusercontent.com/ggdsrll/API-Inazuma-Eleven/main/InazumaEleven1/Jugadores/Brain/Stronger.png', 'DF', 'Fuego', 'Masculino', 'Brain', 145, 121, 44, 46, 48, 52, 47, 52, 52, 'Inazuma Eleven 1'),
(53, 'Marvel', 'Philip Marvel', 'Extrae fuerzas del pánico que le causó el lavado de cerebro.', 'https://raw.githubusercontent.com/ggdsrll/API-Inazuma-Eleven/main/InazumaEleven1/Jugadores/Brain/Marvel.png', 'DF', 'Montaña', 'Masculino', 'Brain', 143, 108, 44, 53, 52, 48, 49, 50, 51, 'Inazuma Eleven 1'),
(54, 'Leading', 'Harry Leading', 'Empezó a jugar al fútbol para ser famoso, y se dejó lavar el cerebro.', 'https://raw.githubusercontent.com/ggdsrll/API-Inazuma-Eleven/main/InazumaEleven1/Jugadores/Brain/Leading.png', 'DF', 'Aire', 'Masculino', 'Brain', 140, 112, 52, 52, 44, 47, 50, 52, 48, 'Inazuma Eleven 1'),
(55, 'Stiller', 'Patrick Stiller', 'Gracias al lavado de cerebro muestra su verdadera personalidad.', 'https://raw.githubusercontent.com/ggdsrll/API-Inazuma-Eleven/main/InazumaEleven1/Jugadores/Brain/Stiller.png', 'MD', 'Aire', 'Masculino', 'Brain', 134, 117, 53, 45, 47, 52, 44, 46, 53, 'Inazuma Eleven 1'),
(56, 'Oughtry', 'Charles Oughtry', 'Se dejó lavar el cerebro por su hermanito enfermo, muy futbolero.', 'https://raw.githubusercontent.com/ggdsrll/API-Inazuma-Eleven/main/InazumaEleven1/Jugadores/Brain/Oughtry.png', 'MD', 'Montaña', 'Masculino', 'Brain', 127, 113, 55, 52, 47, 52, 46, 44, 48, 'Inazuma Eleven 1'),
(57, 'Tell', 'Francis Tell', 'Dice haber visto apariciones. Cree a pies juntillas lo que le digan.', 'https://raw.githubusercontent.com/ggdsrll/API-Inazuma-Eleven/main/InazumaEleven1/Jugadores/Brain/Tell.png', 'MD', 'Bosque', 'Masculino', 'Brain', 145, 109, 44, 53, 48, 46, 45, 44, 48, 'Inazuma Eleven 1'),
(58, 'Rock', 'Tyron Rock', 'Ha perdido sus sentimientos y hace entradas peligrosas como si nada.', 'https://raw.githubusercontent.com/ggdsrll/API-Inazuma-Eleven/main/InazumaEleven1/Jugadores/Brain/Rock.png', 'MD', 'Fuego', 'Masculino', 'Brain', 149, 112, 51, 46, 46, 48, 48, 47, 52, 'Inazuma Eleven 1'),
(59, 'Kind', 'Victor Kind', 'Le han hecho creer que el juego de su equipo no tiene rival.', 'https://raw.githubusercontent.com/ggdsrll/API-Inazuma-Eleven/main/InazumaEleven1/Jugadores/Brain/Kind.png', 'MD', 'Bosque', 'Masculino', 'Brain', 134, 109, 49, 53, 48, 51, 48, 53, 46, 'Inazuma Eleven 1'),
(60, 'Busta', 'Samuel Buster', 'Se ha vuelto un bruto cuyo juego está al limite de la legalidad.', 'https://raw.githubusercontent.com/ggdsrll/API-Inazuma-Eleven/main/InazumaEleven1/Jugadores/Brain/Busta.png', 'MD', 'Fuego', 'Masculino', 'Brain', 125, 113, 55, 46, 52, 49, 48, 50, 49, 'Inazuma Eleven 1'),
(61, 'Mooney', 'Clive Mooney', 'Después de un partido se olvida de las infracciones que ha cometido.', 'https://raw.githubusercontent.com/ggdsrll/API-Inazuma-Eleven/main/InazumaEleven1/Jugadores/Brain/Mooney.png', 'DL', 'Fuego', 'Masculino', 'Brain', 138, 101, 53, 49, 54, 50, 55, 53, 46, 'Inazuma Eleven 1'),
(62, 'Seller', 'Jonathan Seller', 'Solitario muchacho que padece la necesidad de ganar a toda costa.', 'https://raw.githubusercontent.com/ggdsrll/API-Inazuma-Eleven/main/InazumaEleven1/Jugadores/Brain/Seller.png', 'DL', 'Aire', 'Masculino', 'Brain', 132, 113, 55, 50, 50, 59, 55, 45, 46, 'Inazuma Eleven 1'),
(63, 'Turner', 'Neil Turner', 'Ha pasado de sufrir el desprecio de los demás a sentir desdén por todo.', 'https://raw.githubusercontent.com/ggdsrll/API-Inazuma-Eleven/main/InazumaEleven1/Jugadores/Brain/Turner.png', 'DL', 'Fuego', 'Masculino', 'Brain', 121, 108, 48, 48, 53, 53, 44, 50, 45, 'Inazuma Eleven 1'),
(64, 'Idol', 'Sam Idol', 'Cazatalentos que busca con fervor las estrellas del mañana.', 'https://raw.githubusercontent.com/ggdsrll/API-Inazuma-Eleven/main/InazumaEleven1/Jugadores/Otaku/Idol.png', 'PR', 'Montaña', 'Masculino', 'Otaku', 165, 161, 60, 58, 54, 55, 58, 45, 67, 'Inazuma Eleven 1'),
(65, 'Eldorado', 'Grant Eldorado', 'Ama los juegos de lucha. Juega con personajes que nadie elige.', 'https://raw.githubusercontent.com/ggdsrll/API-Inazuma-Eleven/main/InazumaEleven1/Jugadores/Otaku/Eldorado.png', 'PR', 'Fuego', 'Masculino', 'Otaku', 158, 144, 49, 63, 61, 69, 43, 28, 49, 'Inazuma Eleven 1'),
