(85, 'Master', 'Alan Master', 'Este incansable jugador nunca deja de luchar. Los cascos que lleva le dan poder y seguridad.', 'https://raw.githubusercontent.com/ggdsrll/API-Inazuma-Eleven/main/InazumaEleven1/Jugadores/Royal_Academy/Master.png', 'MD', 'Aire', 'Masculino', 'Royal Academy', 165, 168, 64, 64, 72, 69, 64, 62, 66, 'Inazuma Eleven 1'),
