(88, 'Waldon', 'Herman Waldon', 'Tiene a su equipo en alta estima y desprecia a todos los demás.', 'https://raw.githubusercontent.com/ggdsrll/API-Inazuma-Eleven/main/InazumaEleven1/Jugadores/Royal_Academy/Waldon.png', 'MD', 'Aire', 'Masculino', 'Royal Academy', 189, 188, 76, 64, 72, 79, 70, 57, 69, 'Inazuma Eleven 1'),
