(441, 'Jack (IJ)', 'Jack Wallside', '¡Este defensa es grande como una muralla! Aunque un poco miedica.', 'https://raw.githubusercontent.com/ggdsrll/API-Inazuma-Eleven/main/InazumaEleven3/Jugadores/Inazuma_Japon/Jack_(IJ).png', 'DF', 'Montaña', 'Masculino', 'Inazuma Japón', 113, 116, 40, 53, 62, 66, 49, 65, 54, 'Inazuma Eleven 3'),
