(459, 'Heat (NJ)', 'Ethan Whitering', 'Amigo de la infancia de Torch. Se entrenó para ser mas fuerte.', 'https://raw.githubusercontent.com/ggdsrll/API-Inazuma-Eleven/main/InazumaEleven3/Jugadores/Neo_Japon/Heat_(NJ).png', 'PR', 'Bosque', 'Masculino', 'Neo Japón', 133, 128, 52, 79, 60, 60, 62, 71, 55, 'Inazuma Eleven 3'),
(460, 'Master (NJ)', 'Alan Master', 'Los cascos le dan poder. Marea a los rivales al ritmo de la música.', 'https://raw.githubusercontent.com/ggdsrll/API-Inazuma-Eleven/main/InazumaEleven3/Jugadores/Neo_Japon/Master_(NJ).png', 'DF', 'Aire', 'Masculino', 'Neo Japón', 120, 124, 60, 64, 58, 69, 59, 62, 66, 'Inazuma Eleven 3'),
(461, 'Zohen (NJ)', 'Zack Cummings', 'Domina las artes marciales y corta el paso a cualquiera con su cuerpo.', 'https://raw.githubusercontent.com/ggdsrll/API-Inazuma-Eleven/main/InazumaEleven3/Jugadores/Neo_Japon/Zohen_(NJ).png', 'DF', 'Montaña', 'Masculino', 'Neo Japón', 115, 118, 68, 76, 53, 70, 56, 56, 58, 'Inazuma Eleven 3'),
