(463, 'Hatch (NJ)', 'Daniel Hatch', 'Delantero estrella de la Royal. Sus largas piernas son su mejor arma.', 'https://raw.githubusercontent.com/ggdsrll/API-Inazuma-Eleven/main/InazumaEleven3/Jugadores/Neo_Japon/Hatch_(NJ).png', 'DF', 'Bosque', 'Masculino', 'Neo Japón', 111, 121, 60, 55, 68, 68, 52, 61, 64, 'Inazuma Eleven 3'),
