(465, 'Hillvalley (NJ)', 'Mark Hillvalley', '﻿Hijo de granjeros que se levanta muy pronto para cuidar el ganado.', 'https://raw.githubusercontent.com/ggdsrll/API-Inazuma-Eleven/main/InazumaEleven3/Jugadores/Neo_Japon/Hillvalley_(NJ).png', 'DF', 'Montaña', 'Masculino', 'Neo Japón', 134, 108, 40, 56, 52, 79, 63, 66, 53, 'Inazuma Eleven 3'),
(466, 'Turner (NJ)', 'Neil Turner', 'Era tranquilo hasta que le lavaron el cerebro. Se ha vuelto agresivo.', 'https://raw.githubusercontent.com/ggdsrll/API-Inazuma-Eleven/main/InazumaEleven3/Jugadores/Neo_Japon/Turner_(NJ).png', 'MD', 'Fuego', 'Masculino', 'Neo Japón', 121, 125, 57, 58, 70, 52, 62, 60, 55, 'Inazuma Eleven 3'),
