(470, 'Wittz (NJ)', 'Wilbur Watkins', 'Apunta a rivales con su chut para que salgan por los aires.', 'https://raw.githubusercontent.com/ggdsrll/API-Inazuma-Eleven/main/InazumaEleven3/Jugadores/Neo_Japon/Wittz_(NJ).png', 'DL', 'Bosque', 'Masculino', 'Neo Japón', 117, 123, 78, 67, 62, 53, 48, 46, 67, 'Inazuma Eleven 3'),
(471, 'Zell (NJ)', 'Zeke Valanche', 'Confía plenamente en su destreza y culpa a los demás si algo sale mal.', 'https://raw.githubusercontent.com/ggdsrll/API-Inazuma-Eleven/main/InazumaEleven3/Jugadores/Neo_Japon/Zell_(NJ).png', 'DL', 'Aire', 'Masculino', 'Neo Japón', 125, 128, 58, 57, 52, 75, 63, 68, 60, 'Inazuma Eleven 3');
